        let t = Transport::new(48_000);
        t.play();

        // Advance past the first beat boundary.
        let c = t.advance(24_001).expect("should cross beat 0");
        assert_eq!(c.total_beat, 1, "first crossing is beat 1 (from 0)");
        assert_eq!(c.beat_in_bar, 1);
        assert_eq!(c.bar, 0);

